inline constexpr std::size_t kMirrorPairCount =
    sizeof(kMirrorPairs) / sizeof(kMirrorPairs[0]);

// Returns the Bidi_Class of a Unicode scalar value.  The table covers
// 0..10FFFF, so the fallback only guards against corrupt input.
inline auto lookupClass(std::uint32_t codepoint) -> BidiClass
{
    std::size_t low = 0;
    std::size_t high = kClassRangeCount;
    while (low < high)
    {
        const std::size_t middle = low + (high - low) / 2;
        if (kClassRanges[middle].last < codepoint)
        {
            low = middle + 1;
        }
        else
        {
            high = middle;
        }
    }
    if (low < kClassRangeCount && kClassRanges[low].first <= codepoint)
    {
        return kClassRanges[low].cls;
    }
    return BidiClass::l;
}

// Returns the bracket properties for a code point, or nullptr when the
// code point is not an opening or closing paired bracket.
inline auto lookupBracket(std::uint32_t codepoint) -> const BracketPair *
{
    std::size_t low = 0;
    std::size_t high = kBracketPairCount;
    while (low < high)
    {
        const std::size_t middle = low + (high - low) / 2;
        if (kBracketPairs[middle].codepoint < codepoint)
        {
            low = middle + 1;
        }
        else
        {
            high = middle;
        }
    }
    if (low < kBracketPairCount && kBracketPairs[low].codepoint == codepoint)
    {
        return &kBracketPairs[low];
    }
    return nullptr;
}

// Returns the Bidi_Mirroring_Glyph of a code point, or the code point
// itself when the character has no mirror mapping.
inline auto lookupMirror(std::uint32_t codepoint) -> std::uint32_t
{
    std::size_t low = 0;
    std::size_t high = kMirrorPairCount;
    while (low < high)
    {
        const std::size_t middle = low + (high - low) / 2;
        if (kMirrorPairs[middle].codepoint < codepoint)
        {
            low = middle + 1;
        }
        else
        {
            high = middle;
        }
    }
    if (low < kMirrorPairCount && kMirrorPairs[low].codepoint == codepoint)
    {
        return kMirrorPairs[low].mirrored;
    }
    return codepoint;
}

